<template>
  <v-container fluid class="pa-6">
    <div class="d-flex align-center justify-space-between flex-wrap ga-3 mb-5"><div><h1 class="text-h4">Commissions</h1><p class="text-body-2 text-medium-emphasis mt-2">Commission on service charges after discount. Admin approval creates the payable balance; payment waits for full invoice payment.</p></div><v-btn prepend-icon="mdi-refresh" variant="tonal" :loading="loading" @click="load">Refresh</v-btn></div>
    <v-alert v-if="error" type="error" variant="tonal" class="mb-4" closable @click:close="error = ''">{{ error }}</v-alert>
    <v-alert v-if="notice" type="success" variant="tonal" class="mb-4" closable @click:close="notice = ''">{{ notice }}</v-alert>
    <v-tabs v-model="tab" color="primary" class="mb-5"><v-tab value="statements">Statements</v-tab><v-tab v-if="access.manage" value="rules">Criteria settings</v-tab></v-tabs>
    <template v-if="tab === 'statements'">
      <v-card rounded="xl" class="pa-4 mb-5" variant="flat"><v-row align="center"><v-col cols="12" md="3"><v-select v-if="access.view === 'all'" v-model="filters.staff_id" :items="choices.staff" item-title="name" item-value="id" clearable label="All staff" hide-details density="compact" /></v-col><v-col cols="6" md="3"><v-text-field v-model="filters.from" type="date" label="Invoice date from" hide-details density="compact" /></v-col><v-col cols="6" md="3"><v-text-field v-model="filters.to" type="date" label="Invoice date to" hide-details density="compact" /></v-col><v-col cols="12" md="3"><v-btn color="primary" :loading="loading" @click="loadStatement">Apply filters</v-btn></v-col></v-row></v-card>
      <v-row class="mb-4"><v-col v-for="card in cards" :key="card.key" cols="6" md="auto" class="flex-grow-1"><v-card rounded="xl" class="pa-4" variant="flat"><div class="text-caption text-medium-emphasis">{{ card.label }}</div><div class="text-h6 mt-2" :class="card.color">{{ card.key==='eligible_count'?'':'AED ' }}{{ card.key==='eligible_count'?(totals[card.key] || 0):money(totals[card.key]) }}</div></v-card></v-col></v-row>
      <v-card v-if="access.view === 'all' && staffSummary.length" rounded="xl" class="pa-4 mb-5" variant="flat"><h2 class="text-h6 mb-3">Staff summary</h2><v-data-table :headers="staffHeaders" :items="staffSummary" density="compact" :items-per-page="10"><template v-for="key in ['pending','approved','balance','paid']" :key="key" #[`item.${key}`]="{ item }">AED {{ money(item[key]) }}</template></v-data-table></v-card>
      <v-card rounded="xl" class="pa-4" variant="flat"><div class="d-flex justify-space-between align-center mb-3"><h2 class="text-h6">Commission statement</h2><v-btn v-if="access.manage" size="small" variant="tonal" prepend-icon="mdi-history" @click="backfillDialog = true">Recalculate existing invoices</v-btn></div>
        <v-data-table :headers="entryHeaders" :items="entries" :loading="loading" :items-per-page="20" no-data-text="No commissions for this period. Assign a customer salesperson and configure commission criteria.">
          <template #item.invoice_number="{ item }"><strong>{{ item.invoice_number }}</strong><div class="text-caption">{{ item.invoice_date }}</div></template>
          <template #item.formula="{ item }"><div>AED {{ money(item.service_charge) }} × {{ item.percentage }}%</div><div class="text-caption text-medium-emphasis">{{ item.status.startsWith('Legacy')?'Historical calculation':'Service charge after discount' }}</div></template>
          <template #item.amount="{ item }">AED {{ money(item.amount) }}</template><template #item.paid="{ item }">AED {{ money(item.paid) }}</template><template #item.balance="{ item }">AED {{ money(item.balance) }}</template>
          <template #item.status="{ item }"><v-chip size="small" :color="item.status === 'Paid' ? 'success' : item.payable > 0 ? 'primary' : item.status === 'Voided' ? 'grey' : 'warning'">{{ item.status }}</v-chip><div v-if="item.balance>0 && !item.payable" class="text-caption mt-1">Awaiting invoice payment</div></template>
          <template #item.actions="{ item }"><div class="d-flex ga-1"><v-btn v-if="access.approve && item.can_approve" size="small" color="success" variant="tonal" @click="error='';review={entry:item,decision:'Approved',reason:''}">Approve</v-btn><v-btn v-if="access.approve && item.can_reject" size="small" color="error" variant="text" @click="error='';review={entry:item,decision:'Rejected',reason:''}">Reject</v-btn><v-btn v-if="access.pay && item.payable > 0" size="small" variant="tonal" color="primary" @click="openPayment(item)">Pay</v-btn><v-btn size="small" variant="text" icon="mdi-history" title="Payment history" @click="history = item" /></div></template>
        </v-data-table>
      </v-card>
    </template>
    <template v-else-if="tab === 'rules' && access.manage">
      <v-card rounded="xl" class="pa-5" max-width="800"><h2 class="text-h6 mb-4">Simple commission criteria</h2>
        <v-switch v-model="criteria.enabled" label="Enable commission" color="primary" />
        <v-text-field v-model="criteria.min_service_charge" type="number" min="0" step="0.01" label="Minimum service charge after discount per invoice (AED)" hint="Eligible when equal to or greater than this value. A positive actual charge is required." persistent-hint class="mb-4" />
        <v-text-field v-model="criteria.percentage" type="number" min="0.01" max="100" step="0.01" label="Commission percentage of actual service charge" />
        <v-alert type="info" variant="tonal" class="mb-4">Actual service charge = invoice service charges minus invoice discount, minimum zero. One recipient: the customer's salesperson. Only approval creates a commission expense. Payment settles that expense after full invoice payment.</v-alert>
        <p class="text-caption mb-4">Changes apply to new calculations. Existing simple calculations keep their saved amounts and review decisions.</p>
        <v-btn color="primary" :loading="saving" :disabled="loading" @click="saveCriteria">Save criteria</v-btn>
      </v-card>
    </template>
    <v-dialog :model-value="!!review" max-width="500" persistent><v-card v-if="review" rounded="xl" class="pa-4"><v-card-title>{{ review.decision==='Approved'?'Approve commission':'Reject commission' }}</v-card-title><v-card-text><p>{{ review.entry.staff_name }} · {{ review.entry.invoice_number }}</p><p class="my-3">AED {{ money(review.entry.amount) }}</p><p class="text-body-2 mb-3">{{ review.decision==='Approved'?'Approval records the expense and staff payable balance. No wallet payment is made.':'Rejection excludes commission from expense and invoice profit calculations.' }}</p><v-textarea v-if="review.decision==='Rejected'" v-model="review.reason" label="Rejection reason" rows="2" maxlength="500" /><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="review=null">Cancel</v-btn><v-btn color="primary" :loading="saving" :disabled="review.decision==='Rejected' && review.reason.trim().length<3" @click="saveReview">Confirm</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="payDialog" max-width="500" persistent><v-card rounded="xl" class="pa-4"><v-card-title>Pay commission</v-card-title><v-card-text><p class="mb-4">{{ payment.entry?.staff_name }} · {{ payment.entry?.invoice_number }}<br />Available: AED {{ money(payment.entry?.payable) }}</p><v-text-field v-model.number="payment.amount" type="number" label="Payment amount (AED)" /><v-select v-model="payment.account_id" :items="wallets" item-title="name" item-value="id" label="Pay from wallet" /><v-text-field v-model="payment.payment_date" type="date" label="Payment date" /><v-textarea v-model="payment.notes" rows="2" maxlength="255" label="Note (optional)" /><p class="text-caption">This settles the approved expense and deducts the selected wallet. No second expense is created.</p></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="payDialog = false">Cancel</v-btn><v-btn color="primary" :loading="saving" :disabled="!payment.account_id || !(payment.amount > 0) || payment.amount > payment.entry?.payable" @click="pay">Record payment</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!history" max-width="650" @update:model-value="value => { if (!value) history = null; }"><v-card v-if="history" rounded="xl" class="pa-4"><v-card-title>Commission history</v-card-title><v-card-text><p>{{ history.staff_name }} · {{ history.invoice_number }}</p><p v-if="history.reviewed_at" class="text-caption">Reviewed {{ new Date(history.reviewed_at).toLocaleString() }}</p><p class="mb-4">{{ history.status }}: AED {{ money(history.service_charge) }} × {{ history.percentage }}%</p><v-alert v-if="history.void_reason || history.rejection_reason" type="warning" variant="tonal">{{ history.void_reason || history.rejection_reason }}</v-alert><p v-if="!history.payments.length" class="text-medium-emphasis">No payments recorded.</p><v-list v-else><v-list-item v-for="p in history.payments" :key="p.id" :title="`AED ${money(p.amount)} · ${p.payment_date}`" :subtitle="p.reversed_at ? `Reversed: ${p.reversal_reason}` : p.notes || 'Paid'"><template #append><v-btn v-if="access.pay && !p.reversed_at" size="small" variant="text" color="error" @click="reverseForm = { id: p.id, reason: '' }; reverseDialog = true">Reverse</v-btn></template></v-list-item></v-list></v-card-text><v-card-actions><v-spacer /><v-btn @click="history = null">Close</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="reverseDialog" max-width="480" persistent><v-card rounded="xl" class="pa-4"><v-card-title>Reverse commission payment</v-card-title><v-card-text><p class="mb-3">Confirm that the payment is being undone. The amount returns to its original wallet and restores the approved payable balance. The approval expense remains recognised.</p><v-textarea v-model="reverseForm.reason" label="Reason" maxlength="255" rows="3" /></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="reverseDialog = false">Cancel</v-btn><v-btn color="error" :disabled="reverseForm.reason.trim().length < 3" :loading="saving" @click="reverse">Reverse payment</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="backfillDialog" max-width="520" persistent><v-card rounded="xl" class="pa-4"><v-card-title>Recalculate existing invoices</v-card-title><v-card-text><p class="mb-4">Only invoices created after the latest commission activation can be calculated. Earlier invoices, including drafts issued later, are skipped. Existing simple calculations and approvals remain unchanged. No approvals or payments are made.</p><v-text-field v-model="backfill.from" type="date" label="From" /><v-text-field v-model="backfill.to" type="date" label="To" /><p class="text-caption">Up to one year and 500 invoices per calculation.</p></v-card-text><v-card-actions><v-spacer /><v-btn :disabled="saving" @click="backfillDialog = false">Cancel</v-btn><v-btn color="primary" :loading="saving" @click="calculateExisting">Calculate</v-btn></v-card-actions></v-card></v-dialog>
    <v-snackbar v-model="showDialogError" color="error" :timeout="7000">{{ error }}</v-snackbar>
  </v-container>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import { businessDate } from '~/utils/businessDate';
const { $api } = useNuxtApp();
const tab = ref('statements'), loading = ref(false), saving = ref(false), error = ref(''), notice = ref(''), showDialogError = ref(false);
const access = ref({ view: 'own', manage: false, pay: false }), choices = ref({ staff: [], roles: [], services: [] });
const entries = ref([]), totals = ref({}), wallets = ref([]);
const filters = ref({ from: businessDate().slice(0, 7) + '-01', to: businessDate(), staff_id: null });
const payDialog = ref(false), payment = ref({}), history = ref(null), reverseDialog = ref(false), reverseForm = ref({ reason: '' }), backfillDialog = ref(false), backfill = ref({ from: filters.value.from, to: filters.value.to });
const money = value => Number(value || 0).toLocaleString('en-AE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cards = [{key:'eligible_count',label:'Eligible invoices',color:''},{key:'pending',label:'Pending approval',color:'text-warning'},{key:'approved',label:'Approved commission',color:'text-success'},{key:'paid',label:'Commission paid',color:'text-success'},{key:'balance',label:'Balance to be paid',color:'text-primary'},{key:'rejected',label:'Rejected',color:'text-error'}];
const entryHeaders = [{ title: 'Staff', key: 'staff_name' }, { title: 'Invoice', key: 'invoice_number' }, { title: 'Calculation', key: 'formula', sortable: false }, { title: 'Commission', key: 'amount' }, { title: 'Paid', key: 'paid' }, {title:'Balance',key:'balance'}, { title: 'Status', key: 'status' }, { title: '', key: 'actions', sortable: false }];
const staffHeaders = [{title:'Staff',key:'name'},...cards.filter(c=>['pending','approved','balance','paid'].includes(c.key)).map(c=>({title:c.label,key:c.key}))];
const criteria=ref({enabled:false,min_service_charge:0,percentage:5}),review=ref(null);
const staffSummary = computed(() => {
  const grouped = new Map();
  for(const e of entries.value){if(e.status==='Voided')continue;const row=grouped.get(e.staff_id) || {id:e.staff_id,name:e.staff_name,pending:0,approved:0,balance:0,paid:0};row.paid+=Number(e.paid);row.balance+=Number(e.balance);if(['Approved','Paid','Partially paid'].includes(e.status))row.approved+=Number(e.amount);if(e.status==='Pending approval')row.pending+=Number(e.amount);grouped.set(e.staff_id,row);}
  return [...grouped.values()];
});
function failed(err) { error.value = err.response?.data?.message || err.message || 'Unable to complete this action.'; showDialogError.value = true; }
async function fetchStatement() { const { data } = await $api.get('/commissions/statement', { params: filters.value }); entries.value = data.data.entries; totals.value = data.data.totals; }
async function loadStatement() { loading.value = true; error.value = ''; try { await fetchStatement(); } catch (err) { failed(err); } finally { loading.value = false; } }
async function load() { loading.value = true; error.value = ''; try { choices.value = (await $api.get('/commissions/options')).data.data; access.value = choices.value.access; await fetchStatement(); if (access.value.manage) criteria.value = (await $api.get('/commissions/criteria')).data.data; } catch (err) { failed(err); } finally { loading.value = false; } }
async function refreshSaved() { try { await fetchStatement(); if (access.value.manage) criteria.value = (await $api.get('/commissions/criteria')).data.data; } catch { error.value = 'Saved successfully, but refreshing failed. Refresh the page; do not submit again.'; } }
async function saveCriteria(){if(saving.value)return;saving.value=true;error.value='';try{await $api.put('/commissions/criteria',criteria.value);notice.value='Commission criteria saved.';await refreshSaved();}catch(e){failed(e);}finally{saving.value=false;}}
async function saveReview(){if(saving.value)return;saving.value=true;error.value='';try{await $api.post(`/commissions/entries/${review.value.entry.id}/review`,{decision:review.value.decision,reason:review.value.reason});review.value=null;notice.value='Commission decision saved.';await refreshSaved();}catch(e){failed(e);}finally{saving.value=false;}}
function requestKey() { return globalThis.crypto.randomUUID?.() || Array.from(globalThis.crypto.getRandomValues(new Uint8Array(24)), b => b.toString(16).padStart(2, '0')).join(''); }
async function openPayment(entry) { error.value = ''; try { wallets.value = (await $api.get('/wallet/accounts')).data.data; payment.value = { entry, amount: entry.payable, account_id: null, payment_date: businessDate(), notes: '', key: requestKey() }; payDialog.value = true; } catch (err) { failed(err); } }
async function pay() { if (saving.value) return; saving.value = true; error.value = ''; try { const p = payment.value; await $api.post(`/commissions/entries/${p.entry.id}/pay`, { amount: p.amount, account_id: p.account_id, payment_date: p.payment_date, notes: p.notes }, { headers: { 'Idempotency-Key': p.key } }); payDialog.value = false; notice.value = 'Commission payment recorded.'; await refreshSaved(); } catch (err) { failed(err); } finally { saving.value = false; } }
async function reverse() { if (saving.value) return; saving.value = true; error.value = ''; try { await $api.post(`/commissions/payments/${reverseForm.value.id}/reverse`, { reason: reverseForm.value.reason }); reverseDialog.value = false; history.value = null; notice.value = 'Payment reversed; wallet and approved payable balance restored.'; await refreshSaved(); } catch (err) { failed(err); } finally { saving.value = false; } }
async function calculateExisting() { if (saving.value) return; saving.value = true; error.value = ''; try { const { data } = await $api.post('/commissions/calculate-existing', backfill.value); backfillDialog.value = false; notice.value = `${data.data.entries_created} commission entries calculated from ${data.data.invoices_checked} invoices.`; await refreshSaved(); } catch (err) { failed(err); } finally { saving.value = false; } }
onMounted(load);
</script>
<style scoped>
.formula-preview { background: rgba(var(--v-theme-primary), .08); border-radius: 16px; color: rgb(var(--v-theme-primary)); }
</style>
